    a,b=min(p[0] for p in pts),max(p[0] for p in pts); c,d=min(p[1] for p in pts),max(p[1] for p in pts)
    out=[r[:] for r in t]
    for j in range(c,d+1):
        for i in (a,b):
            if out[i][j]==bgc: out[i][j]=2
    for i in range(a,b+1):
        for j in (c,d):
            if out[i][j]==bgc: out[i][j]=2
    return out
for n in (1,2,3,4):
    print(n, f(G['Demo pair %d input'%n])==G['Demo pair %d output'%n])
